begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
('20000000-0000-0000-0000-000000000160','c20_owner@auth.local',now(),'{"provisioned_by_app":"true","username":"c20_owner","display_name":"C20 fake owner","app_role":"OWNER"}');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000160',true);
insert into public.counterparties(name) select 'C20 fake ' || lpad(n::text,4,'0') from generate_series(1,1005) n;
insert into public.transactions(type,transaction_date,amount_vnd,idempotency_key,note)
select 'EXPENSE','2026-01-01'::date+n, case when n=1005 then 9007199254740993 else 1000 end,'c20-expense-'||n,'C20 fake expense' from generate_series(1,1005) n;
insert into public.expenses(transaction_id,category) select id,'C20 category' from public.transactions where idempotency_key like 'c20-expense-%';
set local role authenticated;
select public.reverse_transaction((select id from public.transactions where idempotency_key='c20-expense-1'),'2029-01-01','C20 reverse old expense','c20-reverse-1','2029-01-01');
select is(public.get_general_expenses_page(1,25)->>'totalCount','1005','all 1005 expenses counted');
select is(public.get_general_expenses_page(1,25)->>'totalVnd','9007199255743993','aggregate exact beyond 2^53, excludes reversed old row');
select is(public.get_general_expenses_page(41,25)->>'totalVnd',public.get_general_expenses_page(1,25)->>'totalVnd','aggregate independent of page');
select is(public.get_general_expenses_page(1,25)#>>'{categories,0,amountVnd}','9007199255743993','category exact and authoritative');
select is(public.get_general_expenses_page(1,25)#>>'{items,0,amount_vnd}','9007199254740993','large row serialized as text');
select is(jsonb_typeof(public.get_general_expenses_page(1,25)#>'{items,0,amount_vnd}'),'string','money JSON type is string');
select is(jsonb_array_length(public.get_general_expenses_page(41,25)->'items'),5,'last page accessible');
select is(public.get_general_expenses_page(41,25)#>>'{items,4,reversed}','true','old reversal status available on last page');
select throws_ok($$select public.get_general_expenses_page(null,25)$$,'22023',null,'null page rejected');
select throws_ok($$select public.get_general_expenses_page(2147483647,100)$$,'22023',null,'overflow page rejected');
select public.create_loan_v3((select id from public.counterparties where name='C20 fake 0001'),'C20 exact loan','LENDING',9007199254740993,'2026-01-01',null,30::smallint,0,0::smallint,'c20-loan',null);
select is(public.preview_settlement((select id from public.loans where name='C20 exact loan'),'2026-01-01')->>'principalVnd','9007199254740993','preview exact principal');
select throws_ok($$select public.preview_settlement((select id from public.loans where name='C20 exact loan'),null)$$,'22023',null,'preview requires date');
select throws_ok($$select public.settle_loan_confirmed((select id from public.loans where name='C20 exact loan'),'2026-01-01','c20-settle','9007199254740992','0',null)$$,'PT409',null,'stale preview rejected without write');
select is((select count(*) from public.loan_lifecycle_events where event_type='SETTLEMENT'),0::bigint,'rejected preview writes no settlement');
select lives_ok($$select public.settle_loan_confirmed((select id from public.loans where name='C20 exact loan'),'2026-01-01','c20-settle','9007199254740993','0',null)$$,'confirmed exact settlement succeeds');
select lives_ok($$select public.settle_loan_confirmed((select id from public.loans where name='C20 exact loan'),'2026-01-01','c20-settle','9007199254740993','0',null)$$,'confirmed settlement retry idempotent');
select is((select count(*) from public.transactions where idempotency_key='c20-settle:principal'),1::bigint,'one exact principal payment');
select public.create_loan_v3((select id from public.counterparties where name='C20 fake 0001'),'C20 dated loan','LENDING',1000000,'2026-01-01',null,30::smallint,3,0::smallint,'c20-dated',null);
select isnt(public.preview_settlement((select id from public.loans where name='C20 dated loan'),'2026-01-01')->>'totalVnd',public.preview_settlement((select id from public.loans where name='C20 dated loan'),'2026-01-10')->>'totalVnd','selected date changes authoritative total');
create temporary table old_preview as select public.preview_settlement((select id from public.loans where name='C20 dated loan'),'2026-01-10') as value;
select public.record_financial_transaction((select id from public.loans where name='C20 dated loan'),'PRINCIPAL_PAYMENT','2026-01-05',1000,'c20-intervening',null,'2026-01-10');
select throws_ok($$select public.settle_loan_confirmed((select id from public.loans where name='C20 dated loan'),'2026-01-10','c20-stale',(select value->>'principalVnd' from old_preview),(select value->>'interestVnd' from old_preview),null)$$,'PT409',null,'intervening transaction invalidates preview');
select is(public.list_loan_summaries_page('2026-01-10',null,null,null,null,null,'name',1,1)->>'totalCount','2','list count independent of one-card page');
select is(jsonb_array_length(public.list_loan_summaries_page('2026-01-10',null,null,null,null,null,'name',2,1)->'items'),1,'second card accessible');
select ok(not (public.list_loan_summaries_page('2026-01-10')#>'{items,0,calculation}' ? 'periods'),'card omits periods payload');
select throws_ok($$select public.get_google_sync_snapshot()$$,'42501',null,'authenticated user cannot export service snapshot');
reset role;
insert into public.notifications(user_id,type,notification_date,title,body,idempotency_key)
select '20000000-0000-0000-0000-000000000160','LOAN_OVERDUE','2026-01-01'::date+n,'C20 fake notice','9007199254740993','c20-notice-'||n from generate_series(1,125) n;
create temporary table snapshot_before as select public.get_google_sync_snapshot() value;
select is(jsonb_array_length((select value#>'{tables,counterparties}' from snapshot_before)),1005,'snapshot includes all counterparties beyond API limit');
select is(jsonb_array_length((select value#>'{tables,notifications}' from snapshot_before)),125,'snapshot includes old notifications');
select is(public.get_google_sync_snapshot()->>'sourceVersion',(select value->>'sourceVersion' from snapshot_before),'unchanged data produces same cursor');
update public.notifications set read_at=now() where idempotency_key='c20-notice-1';
select isnt(public.get_google_sync_snapshot()->>'sourceVersion',(select value->>'sourceVersion' from snapshot_before),'read_at change advances cursor');
select ok(not exists(select 1 from jsonb_array_elements(public.get_google_sync_snapshot()#>'{tables,auditLogs}') row where row ?| array['old_data','new_data','endpoint','p256dh','auth_secret']),'snapshot exposes sanitized audit metadata only');
select is((select provolatile::text from pg_proc where oid='public.get_google_sync_snapshot()'::regprocedure),'s','snapshot uses single stable SQL snapshot');
select * from finish();
rollback;
